use vstd::prelude::*;

verus! {

    // Specification of the desired property:
    // All characters in the sequence from index 1 up to len-1
    // are equal to the character at index 0.
    spec fn all_same(v: Seq<char>) -> bool
        decreases v
    {
        forall i: nat :: 1 <= i && i < v.len() ==> v[i] == v[0]
    }

    // Implementation of the check over a Vec<char>
    fn all_characters_same(char_arr: &Vec<char>) -> (result: bool)
        ensures
            // The returned boolean exactly matches the specification
            result == all_same(char_arr@),
    {
        let len = char_arr.len();
        // Trivially true when there are 0 or 1 elements
        if len <= 1 {
            return true;
        }

        // Remember the first character
        let first = char_arr[0];

        // We will iterate from i = 1 up to len, maintaining
        // that `res` records whether all seen elements so far
        // match `first`.
        let mut i: usize = 1;
        let mut res: bool = true;

        while i < len
            invariant
                // i always stays in [1..=len]
                1 <= i <= len,
                // res reflects the predicate on the prefix [1..i)
                res == (forall j: usize :: 1 <= j < i ==> char_arr[j] == first),
            decreases len - i,
        {
            if char_arr[i] != first {
                res = false;
            }
            i = i + 1;
        }

        // At the end i == len, so `res` === forall j in [1..len) . char_arr[j] == first
        res
    }

}

